#include <iostream>
#include <string>
using namespace std;

int main() {
    string old, s;
    getline(cin, old);
    while (getline(cin, s)) {
        if (s.empty()) continue;
        if (s == old) {
            cout << "OK" << endl;
        } else {
            cout << "WARNING" << endl;
        }
    }
    return 0;
}
